export class LinearRegression {
    dataX: number[];
    dataY: number[];
    weight: number = 1;
    bias: number = 0;
    constructor() {
    }
    public fit(x: number[], y: number[] ) {
        this.dataX = x;
        this.dataY = y;
        let xSum = 0;
        let ySum = 0;
        for (let i = 0; i < this.dataX.length; ++i) {
            xSum += this.dataX[i];
            ySum += this.dataY[i];
        }
        const xMean = xSum / this.dataX.length;
        const yMean = ySum / this.dataY.length;

        let num = 0;
        let den = 0;
        for (let i = 0; i < this.dataX.length; ++i) {
            num += (this.dataX[i] - xMean) * (this.dataY[i] - yMean);
            den += (this.dataX[i] - xMean) * (this.dataX[i] - xMean);
        }
        this.weight = num / den;
        this.bias = yMean - this.weight * xMean;
    }
    public predict(x: number[]) {
        const result = [];
        for(let i = 0; i < x.length; ++i) {
            result.push(this.weight * x[i] + this.bias);
        }
        return result
    }
}

export class LinearRegressionGradientDescent {
    dataX: number[];
    dataY: number[];
    weight: number = 1;
    bias: number = 0;
    learningRate: number = 0.01
    constructor() {

    }
    public fit(x: number[], y: number[], epoch = 10) {
        this.dataX = x;
        this.dataY = y;

        for (let i = 0 ; i < epoch; ++i) {
            this.GradientDescent();
        }
    }
    private GradientDescent() {
        for (let i = 0; i < this.dataX.length; ++i) {
            const x = this.dataX[i];
            const y = this.dataY[i];

            const hypothesis = this.weight * x + this.bias;
            const error = y - hypothesis;

            this.weight = this.weight + (error * x) * this.learningRate;
            this.bias = this.bias + (error) * this.learningRate;
        }
    }
    public predict(x: number[]) {
        const result = [];
        for(let i = 0; i < x.length; ++i) {
            result.push(this.weight * x[i] + this.bias);
        }
        return result
    }
}